function aoo_e(string $v): string {return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function aoo_cli_php(): string {
    foreach(['/usr/bin/php','/usr/local/bin/php'] as $candidate) if(is_file($candidate)&&is_executable($candidate)) return $candidate;
    throw new RuntimeException('PHP CLI executable was not found at /usr/bin/php or /usr/local/bin/php.');
}
function aoo_exec_available(): bool {
    $disabled=array_map('trim',explode(',',(string)ini_get('disable_functions')));
    return function_exists('exec')&&!in_array('exec',$disabled,true);
}
function aoo_job_read(): array {
    if(!is_file(AOO_JOB_FILE))return [];
