    return is_array($j)?$j:[];
}
function aoo_job_write(array $job): void {
    if(!is_dir(AOO_JOB_DIR)&&!mkdir(AOO_JOB_DIR,0770,true)&&!is_dir(AOO_JOB_DIR))throw new RuntimeException('Could not create AUGUR job directory.');
    if(file_put_contents(AOO_JOB_FILE,json_encode($job,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX)===false)throw new RuntimeException('Could not save AUGUR job metadata.');
}
function aoo_job_running(array $job): bool {
    $pid=(int)($job['pid']??0);if($pid<=0)return false;
    $proc='/proc/'.$pid;if(!is_dir($proc))return false;
    $cmdline=@file_get_contents($proc.'/cmdline');if($cmdline===false)return true;
    $script=basename((string)($job['script']??''));if($script==='')return true;
    return str_contains(str_replace("\0",' ',$cmdline),$script);
}
function aoo_tail(string $path,int $lines=120): string {
    if(!is_file($path)||!is_readable($path))return '';
    $all=@file($path,FILE_IGNORE_NEW_LINES);if(!is_array($all))return '';
    return implode("\n",array_slice($all,-$lines));
}
function aoo_result_from_log(string $path): array {
    if(!is_file($path)||!is_readable($path))return [];
    $lines=@file($path,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES);if(!is_array($lines))return [];
    for($i=count($lines)-1;$i>=0;$i--){$line=(string)$lines[$i];if(!str_starts_with($line,'NEPTUNE_RESULT_JSON:'))continue;$d=json_decode(substr($line,strlen('NEPTUNE_RESULT_JSON:')),true);return is_array($d)?$d:[];}
    return [];
}
function aoo_result_summary(array $r): string {
    if(!$r)return '';$parts=[];
    if(isset($r['directory'])&&is_array($r['directory'])){$d=$r['directory'];$parts[]='Directory: '.(int)($d['added']??0).' added, '.(int)($d['updated']??0).' updated, '.(int)($d['skipped']??0).' unchanged'.((int)($d['removed']??0)>0?', '.(int)$d['removed'].' removed':'');}
    if(isset($r['source'])&&is_array($r['source'])){$s=$r['source'];$parts[]='Event source: '.(int)($s['changed']??0).' updated, '.(int)($s['cached']??0).' unchanged, '.(int)($s['skipped']??0).' skipped'.((int)($s['errors']??0)>0?', '.(int)$s['errors'].' errors':'');}
    if(isset($r['epa'])&&is_array($r['epa'])){$e=$r['epa'];if((int)($e['events']??0)||(int)($e['teams']??0))$parts[]='Public EPA: '.(int)($e['events']??0).' events, '.(int)($e['teams']??0).' teams, '.(int)($e['matches']??0).' qualification matches rebuilt';}
    if(isset($r['opr'])&&is_array($r['opr'])){$o=$r['opr'];if((int)($o['events']??0)||(int)($o['team_rows']??0))$parts[]='OPR: '.(int)($o['events']??0).' events, '.(int)($o['team_rows']??0).' team/event ratings rebuilt';}
    if(isset($r['depa'])&&is_array($r['depa'])){$d=$r['depa'];if((int)($d['events']??0)||(int)($d['season_rating_rows']??0)||(int)($d['canonical_evidence_rows']??0))$parts[]='D-EPA: '.(int)($d['events']??0).' public events, '.(int)($d['canonical_evidence_rows']??0).' canonical observations, '.(int)($d['season_rating_rows']??0).' season ratings';}
    elseif(isset($r['public'],$r['network'])&&is_array($r['public'])&&is_array($r['network']))$parts[]='D-EPA: '.(int)($r['public']['events']??0).' public events, '.(int)($r['network']['canonical_evidence_rows']??0).' canonical observations, '.(int)($r['network']['season_rating_rows']??0).' season ratings';
    $errors=(int)($r['errors']??0);if($errors>0&&!isset($r['source']['errors']))$parts[]=$errors.' error(s)';
    return implode(' · ',$parts);
}
function aoo_table_exists(PDO $pdo,string $table): bool {$s=$pdo->prepare('SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$s->execute([$table]);return (int)$s->fetchColumn()>0;}
function aoo_year_stats(PDO $pdo,int $year): array {
