    try{if(aoo_table_exists($pdo,'augur_opr_event_ratings')){$s=$pdo->prepare('SELECT COUNT(*) rows_count,COUNT(DISTINCT tba_event_key) events_count,MAX(calculated_at) latest FROM augur_opr_event_ratings WHERE season_year=?');$s->execute([$year]);$r=$s->fetch()?:[];$out['opr_rows']=(int)($r['rows_count']??0);$out['opr_events']=(int)($r['events_count']??0);$out['latest_opr']=$r['latest']??null;}}catch(Throwable $e){}
    try{if(aoo_table_exists($pdo,'augur_epa_team_directory')){$s=$pdo->prepare('SELECT COUNT(*) teams,MAX(updated_at) latest FROM augur_epa_team_directory WHERE season_year=?');$s->execute([$year]);$r=$s->fetch()?:[];$out['directory_teams']=(int)($r['teams']??0);$out['latest_directory']=$r['latest']??null;}}catch(Throwable $e){}
    try{if(aoo_table_exists($pdo,'augur_depa_public_event_ratings')){$s=$pdo->prepare('SELECT COUNT(*) rows_count,MAX(calculated_at) latest FROM augur_depa_public_event_ratings WHERE season_year=?');$s->execute([$year]);$r=$s->fetch()?:[];$out['depa_event_rows']=(int)($r['rows_count']??0);$out['latest_depa']=$r['latest']??null;}if(aoo_table_exists($pdo,'augur_depa_public_season_ratings')){$s=$pdo->prepare('SELECT COUNT(*) FROM augur_depa_public_season_ratings WHERE season_year=?');$s->execute([$year]);$out['depa_season_rows']=(int)$s->fetchColumn();}}catch(Throwable $e){}
    return $out;
}
function aoo_validate_year(mixed $value): int {$year=(int)$value;$max=(int)date('Y')+1;if($year<1992||$year>$max)throw new RuntimeException("Year must be between 1992 and {$max}.");return $year;}
function aoo_launch(string $mode,int $startYear,int $endYear): array {
