    $php=aoo_cli_php();$adminDir=__DIR__;
    if($mode==='directory'){$script=$adminDir.'/augur-team-directory-cli.php';$args=[$startYear,$endYear,'--force'];$label='Team-directory refresh';}
    elseif($mode==='opr'){$script=$adminDir.'/augur-opr-rebuild-cli.php';$args=[$startYear,$endYear];$label='OPR-only rebuild';}
    elseif($mode==='depa'){$script=$adminDir.'/augur-depa-backfill-cli.php';$args=[$startYear,$endYear];$label='D-EPA-only rebuild';}
    else{$script=$adminDir.'/augur-epa-backfill-cli.php';$args=[$startYear,$endYear,'--with-depa'];if($mode==='recalc')$args[]='--recalc-only';elseif($mode!=='full')throw new RuntimeException('Unknown AUGUR maintenance mode.');$label=$mode==='recalc'?'Local EPA + OPR + D-EPA recalculation':'Full EPA + OPR + D-EPA backfill';}
    if(!is_file($script)||!is_readable($script))throw new RuntimeException('Required CLI script is missing: '.basename($script));
    if(!is_dir(AOO_JOB_DIR)&&!mkdir(AOO_JOB_DIR,0770,true)&&!is_dir(AOO_JOB_DIR))throw new RuntimeException('Could not create AUGUR job directory.');
    $log=AOO_JOB_DIR.'/augur-'.date('Ymd-His').'.log';$parts=[escapeshellarg($php),escapeshellarg($script)];foreach($args as $arg)$parts[]=escapeshellarg((string)$arg);
    $cmd='nohup '.implode(' ',$parts).' >> '.escapeshellarg($log).' 2>&1 < /dev/null & echo $!';$output=[];$code=0;exec($cmd,$output,$code);$pid=isset($output[0])?(int)trim((string)$output[0]):0;if($code!==0||$pid<=0)throw new RuntimeException('The AUGUR background job could not be started.');
    $job=['pid'=>$pid,'mode'=>$mode,'label'=>$label,'start_year'=>$startYear,'end_year'=>$endYear,'started_at'=>date(DATE_ATOM),'script'=>$script,'log'=>$log];aoo_job_write($job);return $job;
}
function aoo_phase_parse_terms(string $text): array {$terms=[];foreach(preg_split('/\R/',trim($text))?:[] as $line){$line=trim($line);if($line===''||str_starts_with($line,'#'))continue;if(preg_match('/^([+-]?(?:\d+(?:\.\d+)?|\.\d+))\s*\*\s*([A-Za-z0-9_.-]+)$/',$line,$m))$terms[]=['path'=>$m[2],'weight'=>(float)$m[1]];elseif(preg_match('/^[A-Za-z0-9_.-]+$/',$line))$terms[]=['path'=>$line,'weight'=>1.0];else throw new RuntimeException("Invalid mapping line: {$line}. Use field.path or 2 * field.path.");}return $terms;}
function aoo_phase_terms_text(array $terms): string {$lines=[];foreach($terms as $term){if(is_string($term)){$lines[]=$term;continue;}if(!is_array($term))continue;$path=trim((string)($term['path']??''));if($path==='')continue;$weight=is_numeric($term['weight']??null)?(float)$term['weight']:1.0;$lines[]=abs($weight-1.0)<0.000001?$path:($weight.' * '.$path);}return implode("\n",$lines);}
function aoo_flatten_numeric(array $row,string $prefix=''): array {$out=[];foreach($row as $k=>$v){$path=$prefix===''?(string)$k:$prefix.'.'.$k;if(is_array($v))$out+=aoo_flatten_numeric($v,$path);elseif(is_numeric($v))$out[$path]=(float)$v;}ksort($out);return $out;}
function aoo_next_weekly(array $settings): ?DateTimeImmutable {
    if(empty($settings['weekly_enabled']))return null;
    $tz=new DateTimeZone(date_default_timezone_get());$now=new DateTimeImmutable('now',$tz);$day=max(1,min(7,(int)($settings['weekly_day']??1)));$hour=max(0,min(23,(int)($settings['weekly_hour']??3)));$minute=max(0,min(59,(int)($settings['weekly_minute']??0)));
    $candidate=$now->setTime($hour,$minute,0);$delta=($day-(int)$candidate->format('N')+7)%7;$candidate=$candidate->modify('+'.$delta.' days');if($candidate<=$now)$candidate=$candidate->modify('+7 days');return $candidate;
}
function aoo_format_heartbeat_time(?string $iso): string {if(!$iso)return '—';try{$d=new DateTimeImmutable($iso);return $d->setTimezone(new DateTimeZone(date_default_timezone_get()))->format('M j, Y g:i:s A');}catch(Throwable $e){return $iso;}}

