}

$allowedTabs=$isPlatformOwner?['overview','jobs','archive','phase-maps']:['archive','phase-maps'];
$tab=(string)($_GET['tab']??($isPlatformOwner?'overview':'archive'));if(!in_array($tab,$allowedTabs,true))$tab=$isPlatformOwner?'overview':'archive';
$current=(int)date('Y');$year=aoo_validate_year($_GET['year']??$_POST['year']??$current);$flash=null;$phaseNeedsRecalcYear=null;

if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        verify_csrf();$action=(string)($_POST['action']??'');
        if($action==='save_tba_schedule'){
            if(!$isPlatformOwner)throw new RuntimeException('Platform owner access required.');if(!neptune_tba_scheduler_tables_ready($pdo))throw new RuntimeException('Install sql/2026-09-26_tba-scheduler.sql before saving TBA schedules.');
