            $q=$pdo->prepare("INSERT INTO neptune_tba_schedule_settings(id,live_interval_minutes,weekly_enabled,weekly_day,weekly_hour,weekly_minute,updated_by) VALUES(1,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE live_interval_minutes=VALUES(live_interval_minutes),weekly_enabled=VALUES(weekly_enabled),weekly_day=VALUES(weekly_day),weekly_hour=VALUES(weekly_hour),weekly_minute=VALUES(weekly_minute),updated_by=VALUES(updated_by),updated_at=CURRENT_TIMESTAMP");$q->execute([$liveInterval,$weeklyEnabled,$weeklyDay,$weeklyHour,$weeklyMinute,$uid]);
