        }elseif($action==='phase_save'||$action==='phase_delete'){
            if(!augur_epa_phase_maps_ready($pdo))throw new RuntimeException('Run the phase-map SQL migration first.');$tab='phase-maps';
            if($action==='phase_delete'){$s=$pdo->prepare('DELETE FROM augur_epa_phase_maps WHERE season_year=?');$s->execute([$year]);augur_epa_phase_map($pdo,$year,true);$flash=['good','Custom phase mapping removed.','AUGUR will use its historical/automatic fallback for '.$year.'.'];$phaseNeedsRecalcYear=$year;}
            else{$allowed=['sum','remainder','unavailable'];$map=['version'=>1];foreach(['auto','teleop','endgame'] as $phase){$mode=(string)($_POST[$phase.'_mode']??'sum');if(!in_array($mode,$allowed,true))$mode='sum';$map[$phase]=['mode'=>$mode,'terms'=>$mode==='sum'?aoo_phase_parse_terms((string)($_POST[$phase.'_terms']??'')):[]];}$map['modeled_subtract']=aoo_phase_parse_terms((string)($_POST['modeled_subtract']??''));$reconcile=(string)($_POST['reconcile']??'teleop');$map['reconcile']=in_array($reconcile,['','auto','teleop','endgame'],true)?$reconcile:'teleop';$json=json_encode($map,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);if($json===false)throw new RuntimeException('Could not encode phase mapping.');$uid=(int)($u['id']??0);$uid=$uid>0?$uid:null;$s=$pdo->prepare("INSERT INTO augur_epa_phase_maps(season_year,mapping_json,enabled,notes,updated_by) VALUES(?,?,1,?,?) ON DUPLICATE KEY UPDATE mapping_json=VALUES(mapping_json),enabled=1,notes=VALUES(notes),updated_by=VALUES(updated_by),updated_at=CURRENT_TIMESTAMP");$s->execute([$year,$json,trim((string)($_POST['notes']??'')),$uid]);augur_epa_phase_map($pdo,$year,true);$flash=['good','Phase mapping saved for '.$year.'.','The raw TBA archive is unchanged. Recalculate the season to apply the new phase decomposition.'];$phaseNeedsRecalcYear=$year;}
