<script>(()=>{const endpoint=<?=json_encode(base_url('api/augur-epa-admin.php'))?>,csrf=<?=json_encode(csrf_token())?>,logEl=document.getElementById('epaLog'),bar=document.getElementById('epaProgressBar'),startBtn=document.getElementById('epaBackfillBtn'),stopBtn=document.getElementById('epaStopBtn');let stopped=false,running=false;const log=m=>{logEl.textContent+='\n'+m;logEl.scrollTop=logEl.scrollHeight;};const post=async data=>{const body=new URLSearchParams({...data,csrf});const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||`HTTP ${r.status}`);return j;};stopBtn.addEventListener('click',()=>{stopped=true;log('Stop requested. Current request will finish, then the run will pause.');});startBtn.addEventListener('click',async()=>{if(running)return;let a=Number(document.getElementById('epaStartYear').value),b=Number(document.getElementById('epaEndYear').value);if(a>b)[a,b]=[b,a];stopped=false;running=true;startBtn.disabled=true;stopBtn.disabled=false;logEl.textContent='Starting EPA archive backfill…';const total=Math.max(1,b-a+1);let index=0;try{for(let y=a;y<=b;y++){if(stopped)break;log(`\n${y}: discovering/checking events…`);while(!stopped){const step=await post({action:'process_year_step',year:y});if(step.done)break;log(`${y} · ${step.event_key} · ${step.event_name} · remaining ${step.remaining}`);await new Promise(r=>setTimeout(r,350));}if(stopped)break;log(`${y}: recalculating season from local samples…`);const recalc=await post({action:'recalculate_year',year:y});log(`${y}: complete · ${recalc.result.events} rated events · ${recalc.result.matches} qualification matches.`);index++;bar.style.width=`${Math.round(index/total*100)}%`; }log(stopped?'Backfill paused. Run it again to resume.':'Backfill complete.');}catch(e){log(`ERROR: ${e.message}`);}running=false;startBtn.disabled=false;stopBtn.disabled=true;});})();</script>
