hp endforeach;?></select><label>Notes</label><textarea name="notes" rows="5"><?=aoo_e($phaseNotes)?></textarea></div><div class="epm-box"><h3 style="margin-top:0">Apply changes</h3><p class="epm-help">Saving changes only updates the mapping. Neptune will offer a one-click season recalculation afterward; no raw TBA re-download is required.</p></div></div><div class="toolbar" style="margin-top:14px"><button type="submit"><i class="fa-solid fa-floppy-disk"></i> Save <?=$year?> Mapping</button></div></form>
