<?php if($isPlatformOwner):?><dialog id="augurConfirmDialog" class="ao-confirm"><div class="ao-confirm-body"><h3>Run AUGUR data update?</h3><p id="augurConfirmText" class="muted">This job runs in the background.</p></div><div class="ao-confirm-actions"><button type="button" class="secondary" id="augurCancelRun">Cancel</button><button type="button" id="augurConfirmRun"><i class="fa-solid fa-play"></i> Start Update</button></div></dialog>
<script>(()=>{const form=document.getElementById('augurRunForm');if(!form)return;const dot=document.getElementById('augurJobDot'),title=document.getElementById('augurJobTitle'),meta=document.getElementById('augurJobMeta'),log=document.getElementById('augurJobLog'),terminal=document.getElementById('augurTerminal'),summaryBox=document.getElementById('augurJobSummary'),summaryText=document.getElementById('augurJobSummaryText'),showLog=document.getElementById('augurShowLog'),confirmDialog=document.getElementById('augurConfirmDialog'),confirmText=document.getElementById('augurConfirmText'),cancelRun=document.getElementById('augurCancelRun'),confirmRun=document.getElementById('augurConfirmRun');let allowSubmit=false,lastLog=<?=json_encode($logTail,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?>;const syncButton=running=>{const btn=document.getElementById('augurRunButton');if(!btn)return;btn.disabled=!!running;btn.innerHTML=running?'<i class="fa-solid fa-play"></i> <span>Job Running</span>':'<i class="fa-solid fa-play"></i> <span>Run Update</span>';};form.addEventListener('submit',e=>{if(allowSubmit)return;e.preventDefault();const mode=form.querySelector('[name="mode"]')?.selectedOptions?.[0]?.textContent?.trim()||'AUGUR update',start=form.querySelector('[name="start_year"]')?.value||'',end=form.querySelector('[name="end_year"]')?.value||start;confirmText.textContent=`${mode} for ${start}${end!==start?`–${end}`:''}. The job runs in the background and this page does not need to stay open.`;if(typeof confirmDialog.showModal==='function')confirmDialog.showModal();else{allowSubmit=true;form.requestSubmit();}});cancelRun?.addEventListener('click',()=>confirmDialog.close());confirmRun?.addEventListener('click',()=>{allowSubmit=true;confirmDialog.close();form.requestSubmit();});showLog?.addEventListener('click',()=>{terminal.hidden=!terminal.hidden;if(!terminal.hidden){log.textContent=lastLog||'No log output is available.';showLog.innerHTML='<i class="fa-solid fa-xmark"></i> Hide Last Log';}else{log.textContent='';showLog.innerHTML='<i class="fa-solid fa-file-lines"></i> Show Last Log';}});async function refresh(){try{const r=await fetch(<?=json_encode(base_url('admin/augur-operations.php?status=1'))?>,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}});if(!r.ok)return;const d=await r.json();if(!d.job||!Object.keys(d.job).length)return;dot?.classList.toggle('running',!!d.running);if(title)title.textContent=d.job.label||'AUGUR job';if(meta)meta.textContent=`PID ${d.job.pid||'—'} · ${d.job.start_year||'—'}–${d.job.end_year||'—'} · ${d.running?'Running':'Completed'}`;syncButton(!!d.running);lastLog=typeof d.log==='string'?d.log:'';if(d.running){if(terminal)terminal.hidden=false;if(showLog)showLog.hidden=true;if(log)log.textContent=lastLog;}else{if(terminal)terminal.hidden=true;if(log)log.textContent='';if(showLog){showLog.hidden=false;showLog.innerHTML='<i class="fa-solid fa-file-lines"></i> Show Last Log';}if(summaryBox&&summaryText){summaryText.textContent=d.summary||'';summaryBox.hidden=!d.summary;}}}catch(e){}}refresh();setInterval(refresh,4000);})();</script><?php endif;?>
